      "achados": [
        {
          "proposicao": "Na auditoria do sistema de detecção de fogo e gás foram considerados, entre outros aspectos, filosofias de detecção, lógicas de votação, gestão de inibições, critérios de alocação e testes dos detectores, além da implementação de recomendações de estudos de dispersão de gases.",
          "trechos": [
            "E8723b18fee5abd83:0:694"
          ],
          "condicoes": [
            "no contexto de auditoria temática do sistema de detecção de fogo e gás"
          ],
          "limites": [
            "o trecho lista aspectos verificados, mas não detalha métodos de teste, comissionamento nem critérios quantitativos de cobertura",
            "não explicita requisitos de alimentação elétrica, redundância ou comunicação"
          ]
        },
        {
          "proposicao": "Foi identificado desvio associado à permissividade para sucessivas inibições na mesma fire zone sem gestão de risco adequada, com possibilidade de redução significante da cobertura do sistema.",
          "trechos": [
            "E8723b18fee5abd83:0:694",
            "E8723b18fee5abd83:694:1384"
          ],
          "condicoes": [
